const CACHE='na-nedelyu-v21';const FILES=['./','./index.html','./style.css','./reference.css','./food-art.svg','./data.js','./catalog.js','./planner.js','./prep-ui.js','./live-catalog.js','./app.js','./account.js','./shopping.js','./builder.js','./recipes.html','./recipe-library.js','./recipe-library.css','./wiki-recipes.json','./vendor/leaflet/leaflet.js','./vendor/leaflet/leaflet.css','./icon.svg','./nyamba.svg','./icon-192.png','./icon-512.png','./food.jpg','./manifest.webmanifest'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(new URL(e.request.url).pathname.startsWith('/api/'))return;if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))})

